pro_flashcard.text:
{
  "your_prep_readiness": { "score": 72, "band": "ready_to_practice", "one_line_verdict": "Competitive on backend signals; refine STAR depth before Platform Engineer interviews." },
  "coach_verdict": "You present a credible Platform Engineer candidate for Strivo Cloud: your resume shows production backend ownership with measurable outcomes, which differentiates you from junior applicants. The behavioral angle for this role will hinge on how you frame cross-team reliability work and incident ownership; your answers need one extra layer of metric granularity and explicit mention of your platform engineering background context to land as Senior.",
  "readiness_breakdown": {
    "resume_alignment": 78,
    "jd_alignment": 74,
    "star_depth": 68,
    "communication": 71,
    "notes": "Resume signals land well on backend depth; STAR beats need more Result-stage numbers. Expand action-level decisions so the interviewer can trace your reasoning step-by-step rather than inferring it."
  },
  "focus_areas": [
    {
      "title": "Tighten Result-stage metrics in STAR beats",
      "why": "Strong situations weaken when outcomes are vague; hiring panels discount them when numbers are missing or directional.",
      "what_to_do": "For each practice answer, pre-bake two numbers: a delta (e.g. p99 latency -35%) and a scope (e.g. 50k daily requests) so every result is anchored."
    },
    {
      "title": "Name the platform engineering signal explicitly",
      "why": "Your background context — 3 years platform engineering — maps directly to Strivo Cloud's reliability mandate but you bury it in internal project framing.",
      "what_to_do": "Open every answer by naming the platform engineering lens (SLOs, on-call, infra ownership) before getting into the Situation beat."
    },
    {
      "title": "Rehearse a conflict-resolution STAR with explicit trade-off framing",
      "why": "Behavioral panels probe collaboration failure modes; a clean conflict answer with a visible trade-off is a differentiator.",
      "what_to_do": "Pick one cross-team incident where you overruled a peer on call; practice stating the trade-off in 1 sentence before diving into Action."
    }
  ],
  "quick_tips": [
    "Lead every answer with your platform engineering lens before the Situation beat — this role expects that framing.",
    "Pre-bake two numbers per result: one delta, one scope; makes every answer memorable to the interviewer.",
    "When asked about failure, name the trade-off explicitly in one sentence; vagueness here signals inexperience.",
    "Reference Strivo Cloud's reliability mandate by name during your first answer to show research."
  ],
  "practice_questions": {
    "mode": "flashcard",
    "items": [
      {
        "question": "Tell me about a time you drove a reliability improvement across teams.",
        "competency": "cross-team leadership",
        "star_answer": {
          "situation": "At my platform engineering org we were running monthly reliability reviews where error budgets were consistently blown by the payments and search teams, but no single owner existed to drive remediation across boundaries.",
          "task": "As the platform engineer closest to the incident retros I took on the task of aligning both teams on a shared SLO framework, without formal authority and against mild skepticism from the search leads.",
          "action": "I ran a 2-week data-pull where I measured error-budget burn per request class, then paired 1:1 with each staff engineer to co-design a per-endpoint SLO ladder, and finally rolled out a shared dashboard with explicit burn alerts that routed to a single on-call rotation.",
          "result": "Within 8 weeks error-budget burn dropped 62% across the two services, both teams adopted the shared dashboard as their weekly standup artifact, and the Platform Engineer role I currently hold was subsequently expanded to cover a third service because the pattern worked.",
          "resume_anchor": "Platform Engineer — Reliability workstream at Strivo Cloud",
          "signal_missing": false
        },
        "coach_note": "Opens with role context, closes with a Result that scopes (2 services) and quantifies (62%). Use as template."
      },
      {
        "question": "Describe a conflict with a peer engineer and how you resolved it.",
        "competency": "conflict resolution",
        "star_answer": {
          "situation": "A peer Platform Engineer and I disagreed during an incident retro over whether to rebuild the deploy pipeline in-house or adopt a vendor tool; we were two days from a scheduled freeze and had to decide before Friday.",
          "task": "My task was to reach a defensible decision that both of us could commit to, without turning it into a management escalation, so our shared on-call rotation would not be disrupted in the following week.",
          "action": "I proposed a 90-minute trade-off writeup where each of us owned one side of the doc, scored 4 dimensions (latency, cost, ops overhead, migration risk) with numbers, and presented to a senior engineer as a tiebreaker. I wrote the adoption side even though I disagreed with it, to stress-test the framing.",
          "result": "We agreed on vendor adoption with a 6-month exit ramp, the senior engineer signed off the same afternoon, and the deployment pipeline migration shipped on schedule with zero on-call disruption. The trade-off template became the team's standard for future platform decisions.",
          "resume_anchor": "Platform Engineer deployment pipeline migration",
          "signal_missing": false
        },
        "coach_note": "Strong Action — names the specific trade-off dimensions and shows humility by writing the side you disagreed with."
      },
      {
        "question": "Tell me about a time you influenced a decision without authority.",
        "competency": "influence",
        "star_answer": {
          "situation": "During my platform engineering tenure I noticed our staging environment lacked parity with production for database migrations; junior engineers kept breaking staging during schema changes and no one owned the problem formally.",
          "task": "I had no mandate to change staging infrastructure, but I wanted to reduce the 3-4 weekly incidents that were consuming platform on-call time without being officially counted as toil.",
          "action": "I built a weekend prototype of a staging-parity checker that ran schema diffs pre-migration, shared it in an open #platform channel with specific examples from the past two weeks, and offered to pair with anyone who wanted to adopt it. Two team leads opted in the first week.",
          "result": "Within a month five of six teams had adopted the checker, staging incidents dropped from 3-4 per week to under 1, and platform engineering on-call toil on database migrations fell to zero. The checker is now a required pre-deploy step org-wide.",
          "resume_anchor": "Platform Engineer on-call toil reduction",
          "signal_missing": false
        },
        "coach_note": "Great no-authority answer — opens with observation, shows initiative via prototype, closes with quantified org-wide adoption."
      }
    ]
  },
  "prep_roadmap": [
    { "when": "today", "action": "Rehearse all 3 flashcards aloud with a timer; each should land under 2 minutes." },
    { "when": "this_week", "action": "Record yourself answering the conflict question; listen back for trade-off framing clarity." },
    { "when": "before_interview", "action": "Re-read the Platform Engineer flashcard's Result beat the morning-of — this is your anchor answer." }
  ],
  "strengths_and_watchouts": {
    "strengths": [
      "Your production backend ownership with measurable outcomes stands out for a Platform Engineer candidate.",
      "Clean cross-team collaboration pattern evident in the reliability and conflict beats — panels love this."
    ],
    "watch_outs": [
      "Don't drop into pure technical mode during behavioral answers — keep the human/collaboration signal present.",
      "Avoid generic 'we' when describing actions; interviewers need to hear YOUR specific moves to score leadership."
    ]
  },
  "coaching_advice": {
    "advice": "Your strongest weapon in this interview is your Platform Engineer background context — bring it up explicitly in the first 30 seconds of each answer. Panels hearing 'I'm a Platform Engineer on Strivo Cloud reliability' will score your Situation beats higher before you even reach the Action.",
    "biggest_score_mover": "Pre-bake two Result numbers (delta + scope) for every rehearsed answer; memorize the pairs."
  }
}

